import type { StructureCheck, StyleId } from "@/lib/types";

import data from "./examples.json";

/**
 * A before/after on the home page. `make examples` writes these with Heya's own staging pipeline
 * (services/api/scripts/make_examples.py); the photos are in public/examples/.
 */
export interface Example {
  id: string;
  title: string;
  style: StyleId;
  /** Where the empty room came from: a real photo, or generated by `room_model`. */
  room: "photo" | "generated";
  room_model: string | null;
  /**
   * Who staged it: Heya's own pipeline ("heya", with `provider` and `model`), or a tool outside it
   * ("external", `provider` names the tool). Either way Heya checked the structure and added the label.
   */
  staged_by: "heya" | "external";
  provider: string;
  model: string | null;
  /** How long staging took; unknown when it happened outside Heya. */
  seconds: number | null;
  structure: StructureCheck;
  width: number;
  height: number;
}

export const EXAMPLES = data as Example[];
